package com.mohymods.kingdomsmp.fishing;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class FishingCatchBookTest {
 @Test void actualCastIdentityCannotAwardTwiceAndCollectionSurvivesWeeklyReset(){var b=new FishingCatchBook();var player=UUID.randomUUID();var cast=UUID.randomUUID();assertTrue(b.record(player,"Angler",cast,Set.of("catfish"),10,100));assertFalse(b.record(player,"Angler",cast,Set.of("tuna"),10,101));assertEquals(Set.of("catfish"),b.player(player).orElseThrow().collection());assertTrue(b.record(player,"Angler",UUID.randomUUID(),Set.of("tuna"),11,200));var saved=FishingCatchBook.load(b.save());assertEquals(Set.of("catfish","tuna"),saved.player(player).orElseThrow().collection());assertEquals(1,saved.standings(10).getFirst().species());assertEquals(1,saved.standings(11).getFirst().species());assertFalse(saved.record(player,"Angler",cast,Set.of("catfish"),11,201));}
 @Test void diversityInsteadOfQuantityAndDeterministicTies(){var b=new FishingCatchBook();var first=UUID.fromString("00000000-0000-0000-0000-000000000001");var second=UUID.fromString("00000000-0000-0000-0000-000000000002");b.record(second,"Second",UUID.randomUUID(),Set.of("bluegill"),1,100);b.record(first,"First",UUID.randomUUID(),Set.of("catfish"),1,100);assertEquals(first,b.standings(1).getFirst().player());b.record(second,"Second",UUID.randomUUID(),Set.of("bluegill"),1,150);assertEquals(100,b.standings(1).get(1).reachedAt());b.record(second,"Second",UUID.randomUUID(),Set.of("tuna"),1,200);assertEquals(second,b.standings(1).getFirst().player());assertEquals(2,b.standings(1).getFirst().species());assertEquals(b.standings(1),FishingCatchBook.load(b.save()).standings(1));}
 @Test void boundsAndUnknownSpeciesFailWithoutReplacingHistoricalProof(){var b=new FishingCatchBook();var p=UUID.randomUUID();b.record(p,"Angler",UUID.randomUUID(),Set.of("catfish"),20,1);for(long week=21;week<40;week++)b.record(p,"Angler",UUID.randomUUID(),Set.of("bluegill"),week,week);assertEquals(8,b.player(p).orElseThrow().weeks().size());assertTrue(b.player(p).orElseThrow().collection().contains("catfish"));assertFalse(b.record(p,"Angler",UUID.randomUUID(),Set.of("tuna"),20,50));assertEquals(8,FishingCatchBook.load(b.save()).player(p).orElseThrow().weeks().size());assertThrows(IllegalArgumentException.class,()->b.record(p,"Angler",UUID.randomUUID(),Set.of("forged"),40,100));var tag=b.save();tag.putInt("schema",2);assertThrows(IllegalArgumentException.class,()->FishingCatchBook.load(tag));}
 @Test void duplicateOrCorruptSavedRowsCannotRegenerateACollection(){var b=new FishingCatchBook();b.record(UUID.randomUUID(),"Angler",UUID.randomUUID(),Set.of("catfish"),1,1);var tag=b.save();var rows=tag.getList("players",Tag.TAG_COMPOUND);rows.add(rows.getCompound(0).copy());var duplicatePlayers=tag;assertThrows(IllegalArgumentException.class,()->FishingCatchBook.load(duplicatePlayers));tag=b.save();tag.getList("players",Tag.TAG_COMPOUND).getCompound(0).getList("collection",Tag.TAG_STRING).add(StringTag.valueOf("catfish"));var duplicateSpecies=tag;assertThrows(IllegalArgumentException.class,()->FishingCatchBook.load(duplicateSpecies));}
}
